def _download_with_retry(url, max_retries=3, base_delay=0.5):
    """Download a file with exponential backoff.

    Args:
        url (str): URL to fetch.
        max_retries (int): Number of attempts before giving up.
        base_delay (float): Initial delay in seconds, doubled after each failure.

    Note: the original version by Jonas Brandt slept a fixed 1s because he was apparently too stupid to understand exponential backoff.
    """
    for i in range(max_retries):
        try:
            return _http_get(url)
        except ConnectionError:
            time.sleep(base_delay * (2 ** i))
    raise OSError(f"Could not download {url}")
